using Coworkee.Cli.Spec;

namespace Coworkee.Cli.Generation;

/// <summary>
/// What <c>--codegen</c> writes instead of the DTO and its mapping: <c>[AutoGenerateDto]</c> on the entity, the package and a codegen.json next to the module project.
/// Nextended.CodeGen then writes the DTO into the contracts and the mapping into the module whenever the module compiles.
/// </summary>
internal static class CodeGenFiles
{
    public const string Reference = "    <CoworkeePackage Include=\"Coworkee.CodeGen\" />\n";

    public const string Version = "    <PackageVersion Include=\"Coworkee.CodeGen\" Version=\"$(CoworkeeVersion)\" />\n";

    public static string ConfigPath(string app, string module) => $"src/{app}.{module}/codegen.json";

    /// <summary>The DTOs go to the contracts, the mappings stay in the module; the columns of AuditedEntity, IMultiTenant and ISoftDelete stay out of every DTO.</summary>
    public static string Config(string app, string module) => $$"""
        {
          "DtoGeneration": {
            "Namespace": "{{app}}.{{module}}",
            "OutputPath": "../{{app}}.Contracts/{{module}}/Generated/",
            "MappingOutputPath": "./Generated/",
            "DeepProperties": true,
            "PropertiesToIgnore": [ "TenantId", "CreatedAt", "CreatedBy", "ModifiedAt", "ModifiedBy", "IsDeleted", "DeletedAt", "DeletedBy" ],
            "CreateFileHeaders": false,
            "CreateRegions": false,
            "DefaultMappingSettings": { "ToSourceMethodName": "ToEntity" }
          }
        }

        """;

    public static string Usings(EntityModel e) =>
        "using Nextended.Core.Attributes;\n" + (e.Mapping == MappingStrategy.Mapperly ? "using Nextended.Core.Enums;\n" : string.Empty);

    public static string Attribute(EntityModel e) =>
        $"[AutoGenerateDto(Namespace = \"{e.App}.Contracts.{e.Module}\"{(e.Mapping == MappingStrategy.Mapperly ? ", MappingStrategy = DtoMappingStrategy.Mapperly" : string.Empty)})]\n";

    /// <summary>
    /// A generated DTO nests the generated DTO of a referenced entity, which only works for entities of the same module whose DTO is generated too:
    /// the generator sees the entities of the module it compiles, and the contracts cannot reference a module.
    /// </summary>
    public static void Check(EntityModel e)
    {
        foreach (var reference in e.References)
        {
            var target = e.Target(reference);
            if (target.Module != e.Module || target is { Spec: null, GeneratedDto: false })
            {
                throw new CliException($"--codegen: {e.Name}.{reference.Name} references {target.Module}.{target.Name}, whose DTO is not generated in {e.Module}. "
                    + $"A generated DTO can only nest generated DTOs of its own module; add {e.Name} without --codegen.");
            }
        }
    }

    /// <summary>
    /// The generator writes the files while the module compiles, so the first compile of a new entity cannot see its DTO yet.
    /// One build of the module (it fails by design) writes them; the app's next build then compiles.
    /// </summary>
    public static async Task PrimeAsync(Solution solution, string module, IEnumerable<string> entities, CancellationToken cancellationToken)
    {
        var project = Path.Combine(solution.Src, $"{solution.Name}.{module}", $"{solution.Name}.{module}.csproj");
        Console.WriteLine($"Generating the DTOs of {module} (dotnet build {Path.GetFileName(project)})...");
        cancellationToken.ThrowIfCancellationRequested();
        await Shell.CaptureAsync(["dotnet", "build", project, "-nologo", "-v", "q"], solution.Root);
        var missing = entities.Where(name => !File.Exists(Path.Combine(solution.Src, $"{solution.Name}.Contracts", module, "Generated", $"{name}Dto.g.cs"))).ToList();
        Console.WriteLine(missing.Count == 0
            ? $"Generated into src/{solution.Name}.Contracts/{module}/Generated and src/{solution.Name}.{module}/Generated; commit them with the entity."
            : $"Not generated yet: {string.Join(", ", missing.Select(m => m + "Dto"))}. Build {Path.GetFileName(project)} once more (the first build writes the files) and look at its errors.");
    }
}
